package br.edu.ufpb.wikiart;

import br.edu.ufpb.wikiart.model.Obra;import br.edu.ufpb.wikiart.service.CatalogoService;import br.edu.ufpb.wikiart.web.ApiController;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ApiController.class) class ApiControllerTest {@Autowired MockMvc mvc;@MockitoBean CatalogoService catalogo;Obra obra=new Obra(0,"A1","Obra A","Desconhecido","Barroco","a.jpg");@BeforeEach void preparar(){when(catalogo.obras(any())).thenReturn(List.of(obra));when(catalogo.porId(0)).thenReturn(obra);when(catalogo.porCodigo("A1")).thenReturn(obra);when(catalogo.pertence(any(),any())).thenReturn(true);when(catalogo.periodos()).thenReturn(List.of(new CatalogoService.Periodo("barroco","Barroco",1)));}
@Test void listaEPagina()throws Exception{mvc.perform(get("/api/periodos")).andExpect(status().isOk()).andExpect(jsonPath("$[0].slug").value("barroco"));mvc.perform(get("/api/obras?size=1")).andExpect(status().isOk()).andExpect(jsonPath("$.conteudo[0].codigoAcervo").value("A1"));}
@Test void validaPaginacao()throws Exception{mvc.perform(get("/api/obras?page=-1")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.codigo").value("PAGINA_INVALIDA"));mvc.perform(get("/api/obras?size=101")).andExpect(status().isBadRequest());mvc.perform(get("/api/obras?ordem=x")).andExpect(status().isBadRequest());}
@Test void comparaEReiniciaSessao()throws Exception{mvc.perform(post("/api/buscas/comparar").contentType("application/json").content("{\"tipo\":\"CODIGO\",\"valor\":\"A1\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.medicoes.length()").value(8));mvc.perform(delete("/api/sessao")).andExpect(status().isNoContent());}
}
